import { expect, expectStatus, test } from "../../fixtures";

test("a certificate that expires today can still be approved", { tag: "@LIF-07" }, async ({ apiAs, factory }) => {
  // Arrange: a vendor in review whose insurance certificate expires today (local date).
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const vendor = await factory.vendor({ as: "member" });
  await factory.upload(vendor.id, "w9");
  await factory.upload(vendor.id, "contract");

  const now = new Date();
  const today = [
    now.getFullYear(),
    String(now.getMonth() + 1).padStart(2, "0"),
    String(now.getDate()).padStart(2, "0"),
  ].join("-");
  const certificate = `Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: ${today}\n`;
  const uploaded = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "insurance_certificate",
      file: { name: "insurance-expires-today.txt", mimeType: "text/plain", buffer: Buffer.from(certificate) },
    },
  });
  const certificateDocument = await expectStatus<{ id: string }>(uploaded, 201);

  await expect
    .poll(
      async () => {
        const documents = await expectStatus<{ status: string }[]>(
          await member.get(`/api/vendors/${vendor.id}/documents`),
          200,
        );
        return documents.map((d) => d.status).sort();
      },
      { message: "extraction finishes for all three documents", timeout: 30_000 },
    )
    .toEqual(["extracted", "extracted", "extracted"]);

  await expectStatus(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
  const pending = await factory.extraction(certificateDocument.id, "member");
  expect(pending.status, "insurance certificate extraction awaits review").toBe("pending_review");

  // Act: the reviewer approves the certificate extraction.
  const response = await reviewer.post(`/api/extractions/${pending.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert: the response and the stored extraction both show it approved.
  const body = await expectStatus<{ status: string }>(response, 200);
  expect(body.status).toBe("approved");
  const stored = await factory.extraction(certificateDocument.id, "reviewer");
  expect(stored.status).toBe("approved");
});
